UPDATE blogs SET title_fr='Quand vous devez recadrer vos images', title_es='Cuando necesitas recortar tus imágenes', title_ko='이미지를 잘라야 할 때', description_fr='Comment recadrer rapidement des images à l''aide de l''outil Image Crop de THRJ.', description_es='Cómo recortar imágenes rápidamente usando la herramienta Recortar imágenes de THRJ.', description_ko='THRJ의 이미지 자르기 도구를 사용하여 이미지를 빠르게 자르는 방법.', content_fr='<div style="font-family : -apple-system, BlinkMacSystemFont, ''Segoe WPC'', ''Segoe UI'', system-ui, ''Ubuntu'', ''Droid Sans'', sans-serif ; taille de police : 14px ; hauteur de ligne : 1.6 ; couleur : #000000 ;">

  <h1>Guide de recadrage d''images : recadrez, faites pivoter et encadrez des photos directement dans votre navigateur</h1>

  <p>Une présentation complète de l''utilisation de l''outil Image Crop sur THRJ. Ce guide explique l''interface utilisateur, les commandes clés et les instructions étape par étape avec des captures d''écran. Que vous ayez besoin de supprimer un bord d''arrière-plan indésirable, de produire un recadrage carré pour Instagram ou de recadrer un portrait, l''outil de recadrage basé sur un navigateur de THRJ est là pour vous. <a href="/image-crop">Ouvrir l''image de recadrage</a></p>

  <br>
  <h2>Qu''est-ce que le recadrage d''image ?</h2>

  <p>Le recadrage d''image consiste à sélectionner une région rectangulaire d''une image et à supprimer tout ce qui se trouve en dehors de cette région. Il s''agit de l''une des opérations de retouche photo les plus fondamentales et elle est utilisée quotidiennement par les créateurs de contenu, les spécialistes du marketing, les gestionnaires de médias sociaux, les photographes et les développeurs.</p>

  <p>Les raisons courantes pour recadrer une image incluent la suppression des éléments indésirables des bords, le recadrage d''un sujet pour améliorer la composition, le redimensionnement aux proportions d''une plate-forme, l''extraction de parties de captures d''écran ou la préparation d''images de produits pour le commerce électronique.</p>

  <p><img src="/screenshots/crop/crop_001.png" alt="Capture d''écran de l''outil de recadrage" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>Présentation vidéo</h2>

  <div style="position : relative ; largeur : 100 % ; padding-bottom : 56,25 % ; hauteur : 0 ; débordement : caché ;">
    <iframe src="https://www.youtube.com/embed/obf1Bh2xsLw" title="Procédure pas à pas de recadrage d''image" frameborder="0" allow="accéléromètre ; lecture automatique ; écriture dans le presse-papiers ; support crypté ; gyroscope ; image dans l''image" allowfullscreen style="position : absolue ; haut : 0 ; gauche : 0 ; largeur : 100 % ; hauteur : 100 % ; bordure : 0;"></iframe>
  </div>

  <br>
  <h2>Étapes rapides</h2>

  <ol>
    <li>Ouvrez l''outil Recadrage d''image depuis le menu principal (Outils → Recadrage d''image) ou visitez <code>/image-crop</code>.</li>
    <li>Faites glisser et amp; déposez une image sur la zone de recadrage ou cliquez pour parcourir et sélectionner un fichier.</li>
    <li>Faites glisser la superposition de recadrage pour encadrer la partie que vous souhaitez conserver. Utilisez les préréglages de rapport hauteur/largeur ou le mode <em>Gratuit</em> pour un recadrage personnalisé.</li>
    <li>Ajustez le zoom (Alt + molette de la souris fonctionne), faites pivoter ou retournez l''image pour affiner le cadrage.</li>
    <li>Cliquez sur <strong>Aperçu</strong> pour générer l''image recadrée, inspectez-la, puis cliquez sur <strong>Télécharger</strong> pour enregistrer le fichier PNG.</li>
  </ol>

  <br>
  <h2>Étape par étape avec captures d''écran</h2>

  <h3>1. Charger une image</h3>
  <p>Cliquez sur la zone de recadrage ou faites glisser un fichier image dessus pour le charger. L''image apparaît dans la fenêtre de recadrage avec une zone de sélection déplaçable.</p>
  <p><img src="/screenshots/crop/crop_001.png" alt="Charger l''image" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>2. Choisissez l''aspect et l''amp; sélectionner une région</h3>
  <p>Sélectionnez un rapport hauteur/largeur dans la liste déroulante (1:1, 16:9, 4:5) ou choisissez Libre pour un recadrage sans contrainte. Faites glisser les coins pour redimensionner la sélection ou déplacez-la pour repositionner le recadrage.</p>
  <p><img src="/screenshots/crop/crop_002.png" alt="Sélectionner la région" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>3. Zoomer, faire pivoter, retourner</h3>
  <p>Utilisez le curseur de zoom ou maintenez Alt + défilement pour zoomer sur l''image à l''intérieur de la fenêtre de recadrage. Utilisez les boutons de rotation pour des pas de 90° ou entrez un angle personnalisé. Utilisez Flip pour refléter horizontalement ou verticalement.</p>
  <p><img src="/screenshots/crop/crop_003.png" alt="Zoom rotation flip" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>4. Aperçu et amp; télécharger</h3>
  <p>Cliquez sur <strong>Aperçu</strong> pour afficher la région recadrée et l''inspecter dans la boîte de dialogue d''aperçu. Une fois satisfait, cliquez sur <strong>Télécharger</strong> pour enregistrer le PNG recadré.</p>
  <p><img src="/screenshots/crop/crop_004.png" alt="Aperçu du résultat" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>Conseils et astuces FAQ</h2>
  <ul>
    <li>Tous les traitements s''exécutent dans votre navigateur : votre image n''est pas téléchargée sur nos serveurs.</li>
    <li>Formats d''image pris en charge : tout format pris en charge par votre navigateur (JPEG, PNG, WebP, GIF, etc.). La sortie est PNG.</li>
    <li>Si le bouton Télécharger est désactivé, cliquez d''abord sur Aperçu pour générer le résultat.</li>
    <li>Utilisez des préréglages (Instagram, YouTube, profil) pour les tailles de cible courantes.</li>
  </ul>

  <br>
  <h2>Guide des proportions pour les plates-formes populaires</h2>
  <tableau>
    <tête>
      <tr><th>Plateforme / utilisation</th><th>Rapport hauteur/largeur</th><th>Pixels (recommandé)</th></tr>
    </tête>
    <corps>
      <tr><td>Publication carrée Instagram</td><td>1:1</td><td>1080 × 1080</td></tr>
      <tr><td>Post portrait Instagram</td><td>4:5</td><td>1080 × 1350</td></tr>
      <tr><td>Histoires / Bobines Instagram</td><td>9:16</td><td>1080 × 1920</td></tr>
      <tr><td>Image de publication Twitter/X</td><td>16:9</td><td>1200 × 675</td></tr>
      <tr><td>Vignette YouTube</td><td>16:9</td><td>1 280 × 720</td></tr>
      <tr><td>Photo de couverture Facebook</td><td>205:78 (~2,63:1)</td><td>820 × 312</td></tr>
      <tr><td>Bannière de profil LinkedIn</td><td>4:1</td><td>1584 × 396</td></tr>
      <tr><td>Photo de profil (la plupart des plateformes)</td><td>1:1</td><td>400 × 400 minimum</td></tr>
      <tr><td>Produit de commerce électronique (Amazon)</td><td>1:1</td><td>1 000 × 1 000 minimum</td></tr>
      <tr><td>Image du héros du blog</td><td>16:9</td><td>1 200 × 675</td></tr>
    </tbody>
  </table>

  <br>
  <h2>Techniques de recadrage pour une meilleure composition</h2>
  <p>Utilisez la règle des tiers, laissez de la marge pour les portraits, supprimez les distractions tout en préservant le contexte et redressez les horizons si nécessaire.</p>

  <br>
  <h2>Utiliser les commandes de rotation et d''inversion</h2>
  <ul>
    <li><strong>Rotation à 90 °</strong> : correction rapide de l''orientation.</li>
    <li><strong>Rotation d''angle personnalisé</strong> : redressez un horizon ou corrigez l''inclinaison.</li>
    <li><strong>Inversion horizontale</strong> : créez des compositions en miroir.</li>
    <li><strong>Retournement vertical</strong> : à utiliser pour des effets créatifs ou des corrections de scanner.</li>
  </ul>

  <br>
  <h2>Questions fréquemment posées</h2>
  <p><strong>Le résultat du recadrage conserve-t-il les métadonnées EXIF ?</strong> Le résultat est une exportation de canevas PNG, qui n''inclut pas les données EXIF d''origine (utile pour la confidentialité).</p>
  <p><strong>Puis-je annuler un recadrage ?</strong> Vous pouvez recharger l''image originale à tout moment pour refaire le recadrage.</p>
  <p><strong>Pourquoi ma sortie est-elle au format PNG alors que mon entrée était au format JPEG ?</strong> L''outil de recadrage exporte au format PNG pour éviter les artefacts de recompression. Si vous avez besoin de JPEG, utilisez le <a href="/image-converter">Image Converter</a>.</p>
  <p><strong>Puis-je recadrer avec une taille de pixel fixe ?</strong> Définissez un rapport hauteur/largeur, puis utilisez le <a href="/image-resizer">Redimensionneur d''image</a> pour redimensionner exactement les pixels.</p>

  <heure />
  <p>Publié par THRJ Tech</p>

</div>', content_es='<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe WPC'', ''Segoe UI'', system-ui, ''Ubuntu'', ''Droid Sans'', sans-serif; tamaño de fuente: 14px; altura de línea: 1,6; color: #000000;">

  <h1>Guía de recorte de imágenes: recorta, rota y encuadra fotos directamente en tu navegador</h1>

  <p>Un tutorial completo para usar la herramienta Recortar imágenes en THRJ. Esta guía explica la interfaz de usuario, los controles clave y las instrucciones paso a paso con capturas de pantalla. Ya sea que necesite eliminar un borde de fondo no deseado, producir un recorte cuadrado para Instagram o reencuadrar un retrato, la herramienta de recorte basada en navegador de THRJ lo tiene cubierto. <a href="/image-crop">Abrir la imagen recortada</a></p>

  <br>
  <h2>¿Qué es el recorte de imágenes?</h2>

  <p>El recorte de imágenes es el proceso de seleccionar una región rectangular de una imagen y descartar todo lo que esté fuera de esa región. Es una de las operaciones de edición de fotografías más fundamentales y la utilizan a diario creadores de contenido, especialistas en marketing, administradores de redes sociales, fotógrafos y desarrolladores.</p>

  <p>Las razones comunes para recortar una imagen incluyen eliminar elementos no deseados de los bordes, reencuadrar un sujeto para mejorar la composición, cambiar el tamaño a la relación de aspecto de una plataforma, extraer partes de capturas de pantalla o preparar imágenes de productos para el comercio electrónico.</p>

  <p><img src="/screenshots/crop/crop_001.png" alt="Captura de pantalla de la herramienta Recortar" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>Video tutorial</h2>

  <div style="posición: relativa; ancho: 100%; padding-bottom: 56,25%; altura: 0; desbordamiento: oculto;">
    <iframe src="https://www.youtube.com/embed/obf1Bh2xsLw" title="Tutorial de recorte de imágenes" frameborder="0" permitir="acelerómetro; reproducción automática; escritura en portapapeles; medios cifrados; giroscopio; imagen en imagen" enablefullscreen style="posición: absoluta; arriba: 0; izquierda: 0; ancho: 100%; alto: 100%; borde: 0;"></iframe>
  </div>

  <br>
  <h2>Pasos rápidos</h2>

  <ol>
    <li>Abra la herramienta Recortar imagen desde el menú principal (Herramientas → Recortar imagen) o visite <code>/image-crop</code>.</li>
    <li>Arrastrar y abrir suelte una imagen en el área de recorte o haga clic para buscar y seleccionar un archivo.</li>
    <li>Arrastre la superposición de recorte para enmarcar la parte que desea conservar. Utilice ajustes preestablecidos de relación de aspecto o el modo <em>Gratis</em> para realizar recortes personalizados.</li>
    <li>Ajusta el zoom (funciona Alt + rueda del mouse), rota o voltea la imagen para ajustar el encuadre.</li>
    <li>Haga clic en <strong>Vista previa</strong> para generar la imagen recortada, inspecciónela y luego haga clic en <strong>Descargar</strong> para guardar el PNG.</li>
  </ol>

  <br>
  <h2>Paso a paso con capturas de pantalla</h2>

  <h3>1. Cargar una imagen</h3>
  <p>Haga clic en el área de recorte o arrastre un archivo de imagen hacia ella para cargarlo. La imagen aparece dentro de la ventana de recorte con un cuadro de selección que se puede arrastrar.</p>
  <p><img src="/screenshots/crop/crop_001.png" alt="Cargar imagen" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>2. Elija aspecto y aspecto seleccione región</h3>
  <p>Elija una relación de aspecto del menú desplegable (1:1, 16:9, 4:5) o elija Gratis para un recorte sin restricciones. Arrastre las esquinas para cambiar el tamaño de la selección o muévala para reposicionar el recorte.</p>
  <p><img src="/screenshots/crop/crop_002.png" alt="Seleccionar región" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>3. Ampliar, rotar, voltear</h3>
  <p>Utilice el control deslizante Zoom o mantenga presionado Alt + desplazamiento para ampliar la imagen dentro de la ventana de recorte. Utilice los botones de rotación para pasos de 90° o ingrese un ángulo personalizado. Utilice Voltear para reflejar horizontal o verticalmente.</p>
  <p><img src="/screenshots/crop/crop_003.png" alt="Zoom rotar flip" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>4. Vista previa y descargar</h3>
  <p>Haga clic en <strong>Vista previa</strong> para representar la región recortada e inspeccionarla en el cuadro de diálogo de vista previa. Cuando esté satisfecho, haga clic en <strong>Descargar</strong> para guardar el PNG recortado.</p>
  <p><img src="/screenshots/crop/crop_004.png" alt="Vista previa del resultado" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>Consejos y recomendaciones Preguntas frecuentes</h2>
  <ul>
    <li>Todo el procesamiento se ejecuta en su navegador; su imagen no se carga en nuestros servidores.</li>
    <li>Formatos de imagen admitidos: cualquier formato que admita su navegador (JPEG, PNG, WebP, GIF, etc.). La salida es PNG.</li>
    <li>Si el botón Descargar está deshabilitado, primero haga clic en Vista previa para generar el resultado.</li>
    <li>Utilice ajustes preestablecidos (Instagram, YouTube, Perfil) para tamaños de destino comunes.</li>
  </ul>

  <br>
  <h2>Guía de proporciones de aspecto para plataformas populares</h2>
  <tabla>
    <cabeza>
      <tr><th>Plataforma/uso</th><th>Relación de aspecto</th><th>Píxeles (recomendado)</th></tr>
    </thead>
    <tcuerpo>
      <tr><td>Publicación cuadrada de Instagram</td><td>1:1</td><td>1080 × 1080</td></tr>
      <tr><td>Publicación de retrato de Instagram</td><td>4:5</td><td>1080 × 1350</td></tr>
      <tr><td>Historias de Instagram/Reels</td><td>9:16</td><td>1080 × 1920</td></tr>
      <tr><td>Imagen de Twitter / X post</td><td>16:9</td><td>1200 × 675</td></tr>
      <tr><td>Miniatura de YouTube</td><td>16:9</td><td>1280 × 720</td></tr>
      <tr><td>Foto de portada de Facebook</td><td>205:78 (~2,63:1)</td><td>820 × 312</td></tr>
      <tr><td>Banner de perfil de LinkedIn</td><td>4:1</td><td>1584 × 396</td></tr>
      <tr><td>Imagen de perfil (la mayoría de las plataformas)</td><td>1:1</td><td>400 × 400 mínimo</td></tr>
      <tr><td>Producto de comercio electrónico (Amazon)</td><td>1:1</td><td>1000 × 1000 mínimo</td></tr>
      <tr><td>Imagen destacada del blog</td><td>16:9</td><td>1200 × 675</td></tr>
    </tbody>
  </tabla>

  <br>
  <h2>Técnicas de recorte para una mejor composición</h2>
  <p>Utilice la regla de los tercios, deje espacio para la cabeza y la apariencia para los retratos, elimine las distracciones preservando el contexto y enderece los horizontes cuando sea necesario.</p>

  <br>
  <h2>Uso de los controles de rotación y volteo</h2>
  <ul>
    <li><strong>Rotación de 90°</strong>: orientación correcta rápidamente.</li>
    <li><strong>Rotación de ángulo personalizada</strong>: endereza un horizonte o corrige la inclinación.</li>
    <li><strong>Giro horizontal</strong>: crea composiciones de espejos.</li>
    <li><strong>Giro vertical</strong>: utilícelo para efectos creativos o correcciones de escáner.</li>
  </ul>

  <br>
  <h2>Preguntas frecuentes</h2>
  <p><strong>¿El resultado del recorte mantiene metadatos EXIF?</strong> El resultado es una exportación de lienzo PNG, que no incluye datos EXIF originales (útil para la privacidad).</p>
  <p><strong>¿Puedo deshacer un recorte?</strong> Puedes volver a cargar la imagen original en cualquier momento para rehacer el recorte.</p>
  <p><strong>¿Por qué mi salida está en PNG cuando mi entrada era JPEG?</strong> La herramienta de recorte exporta a PNG para evitar artefactos de recompresión. Si necesita JPEG, utilice el <a href="/image-converter">Convertidor de imágenes</a>.</p>
  <p><strong>¿Puedo recortar con un tamaño de píxel fijo?</strong> Establezca una relación de aspecto y luego use el <a href="/image-resizer">Image Resizer</a> para escalar a píxeles exactos.</p>

  <hora/>
  <p>Publicado por THRJ Tech</p>

