  <h1>이미지 자르기 가이드 — 브라우저에서 직접 사진 자르기, 회전 및 프레임 지정</h1>

  <p>THRJ에서 이미지 자르기 도구를 사용하는 방법에 대한 전체 안내입니다. 이 가이드에서는 스크린샷을 통해 UI, 주요 컨트롤, 단계별 지침을 설명합니다. 원하지 않는 배경 가장자리를 제거하거나, Instagram용 정사각형 자르기를 생성하거나, 인물 사진의 프레임을 변경해야 하는 경우 THRJ의 브라우저 기반 자르기 도구를 사용하면 됩니다. <a href="/image-crop">자르기 이미지 열기</a></p>

  <br>
  <h2>이미지 자르기란 무엇인가요?</h2>

  <p>이미지 자르기는 이미지의 직사각형 영역을 선택하고 해당 영역 외부의 모든 항목을 삭제하는 프로세스입니다. 이는 가장 기본적인 사진 편집 작업 중 하나이며 콘텐츠 제작자, 마케팅 담당자, 소셜 미디어 관리자, 사진가 및 개발자가 매일 사용합니다.</p>

  <p>이미지를 자르는 일반적인 이유에는 가장자리에서 원치 않는 요소 제거, 구성 개선을 위해 피사체 재구성, 플랫폼의 가로세로 비율 조정, 스크린샷 일부 추출, 전자상거래용 제품 이미지 준비 등이 있습니다.</p>

  <p><img src="/screenshots/crop/crop_001.png" alt="자르기 도구 스크린샷" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>동영상 둘러보기</h2>

  <div 스타일="위치: 상대; 너비: 100%; 패딩 하단: 56.25%; 높이: 0; 오버플로: 숨김;">
