  <br>
  <h2>빠른 단계</h2>

  <올>
    <li>기본 메뉴(도구 → 이미지 자르기)에서 이미지 자르기 도구를 열거나 <code>/image-crop</code>을 방문하세요.</li>
    <li>드래그 앤 앰프; 이미지를 자르기 영역에 놓거나 클릭하여 파일을 찾아 선택하세요.</li>
    <li>자르기 오버레이를 드래그하여 유지하려는 부분의 프레임을 지정하세요. 맞춤 자르기를 위해 가로세로 비율 사전 설정 또는 <em>무료</em> 모드를 사용하세요.</li>
    <li>확대/축소 조정(Alt + 마우스 휠 작동), 이미지 회전 또는 뒤집기를 통해 프레임을 미세 조정합니다.</li>
    <li><strong>미리보기</strong>를 클릭하여 잘린 이미지를 생성하고 검사한 다음 <strong>다운로드</strong>를 클릭하여 PNG를 저장합니다.</li>
  </ol>

  <br>
  <h2>스크린샷을 포함한 단계별</h2>

  <h3>1. 이미지 로드</h3>
  <p>자르기 영역을 클릭하거나 이미지 파일을 드래그하여 로드하세요. 드래그 가능한 선택 상자가 있는 자르기 창 내부에 이미지가 나타납니다.</p>
  <p><img src="/screenshots/crop/crop_001.png" alt="이미지 로드" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>2. 측면 &amp; 지역 선택</h3>
  <p>드롭다운에서 가로세로 비율(1:1, 16:9, 4:5)을 선택하거나 제한 없이 자르려면 무료를 선택하세요. 모서리를 드래그하여 선택 항목의 크기를 조정하거나 이동하여 자르기 위치를 변경하세요.</p>
  <p><img src="/screenshots/crop/crop_002.png" alt="지역 선택" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>3. 확대/축소, 회전, 뒤집기</h3>
  <p>자르기 창 내부의 이미지를 확대/축소하려면 확대/축소 슬라이더를 사용하거나 Alt + 스크롤을 누르세요. 90° 단위로 회전 버튼을 사용하거나 사용자 정의 각도를 입력하세요. 뒤집기를 사용하여 수평 또는 수직으로 미러링합니다.</p>
  <p><img src="/screenshots/crop/crop_003.png" alt="확대/축소 회전 뒤집기" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>4. 미리보기 &amp; 다운로드</h3>
  <p>잘린 영역을 렌더링하고 미리보기 대화상자에서 검사하려면 <strong>미리보기</strong>를 클릭하세요. 만족스러우면 <strong>다운로드</strong>를 클릭하여 잘린 PNG를 저장하세요.</p>
  <p><img src="/screenshots/crop/crop_004.png" alt="결과 미리보기" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
