    <li>지원되는 이미지 형식: 브라우저가 지원하는 모든 형식(JPEG, PNG, WebP, GIF 등). 출력은 PNG입니다.</li>
    <li>다운로드 버튼이 비활성화된 경우 먼저 미리보기를 클릭하여 출력을 생성하세요.</li>
    <li>일반적인 타겟 크기에는 사전 설정(Instagram, YouTube, 프로필)을 사용하세요.</li>
  </ul>

  <br>
  <h2>인기 플랫폼을 위한 화면 비율 가이드</h2>
  <테이블>
    <머리>
