  <br>
  <h2>회전 및 뒤집기 컨트롤 사용</h2>
  <ul>
    <li><strong>90° 회전</strong>: 방향을 빠르게 수정합니다.</li>
    <li><strong>맞춤 각도 회전</strong>: 수평선을 직선화하거나 기울기를 수정합니다.</li>
    <li><strong>가로 뒤집기</strong>: 거울 구성을 만듭니다.</li>
