  <p><strong>자르기를 취소할 수 있나요?</strong> 언제든지 원본 이미지를 다시 로드하여 자르기를 다시 수행할 수 있습니다.</p>
  <p><strong>입력이 JPEG인데 출력이 PNG인 이유는 무엇입니까?</strong> 자르기 도구는 재압축 아티팩트를 방지하기 위해 PNG로 내보냅니다. JPEG가 필요한 경우 <a href="/image-converter">이미지 변환기</a>를 사용하세요.</p>
