  <ul>
    <li><strong>콜라주 및 미리보기</strong>를 눌러 확대/축소 및 마무리 컨트롤이 있는 미리보기 대화상자를 엽니다.</li>
    <li>미리보기 도구를 사용하여 오프셋을 재설정하고 배경/테두리 색상을 변경하거나 내보내기 해상도를 마무리하세요.</li>
  </ul>

  <ol 시작="4">
    <li>생성 및 다운로드</li>
  </ol>

  <p><img src="/screenshots/collage/image-collage004.png" alt="콜라주 다운로드" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p><ul>
    <li>콜라주를 마무리하여 단일 래스터 이미지를 렌더링하고 이를 PNG로 다운로드합니다(또는 더 작은 파일이 필요한 경우 외부에서 JPEG로 변환).</li>
  </ul>

  <br>
  <h2 id="tips--faqs">팁 및 앰프; 자주 묻는 질문</h2>

  <ul>
    <li>모든 구성은 브라우저에서 실행됩니다. 이미지는 명시적으로 업로드하거나 공유하지 않는 한 기기에 남아 있습니다.</li>
    <li>소셜 게시물의 경우 품질과 파일 크기의 적절한 균형을 위해 1200~2048픽셀 사이의 캔버스 너비를 목표로 하세요.</li>
    <li>내보낸 후 이미지가 부드러워지면 고해상도 소스 이미지를 사용하거나 내보내기 캔버스 크기를 늘리세요.</li>
    <li>내보낼 때 애니메이션 소스(GIF/WebP)가 단일 프레임으로 병합됩니다.</li>
  </ul>

  <br>
  <h2 id="common-use-cases">일반적인 사용 사례</h2>

  <p><strong>소셜 미디어 콘텐츠</strong>: Instagram 캐러셀과 Facebook 앨범은 콜라주만큼 좋은 성능을 발휘합니다. 2×2 또는 3×2 그리드는 정사각형 또는 가로형 기둥에 이상적입니다.</p>
  <p><strong>전자상거래 제품 목록</strong>: 단일 히어로 이미지에 다양한 각도에서 제품을 표시합니다. 소매업체에서는 다양한 색상 변형이 포함된 2×3 그리드를 사용하는 경우가 많습니다.</p>
  <p><strong>여행 및 이벤트 요약</strong>: 12가지 하이라이트를 결합하여 벽 포스터나 인쇄 가능한 카드를 만듭니다. 3열 그리드의 세로 방향은 인쇄된 사진첩에 적합합니다.</p>
  <p><strong>부동산</strong>: 매물 목록이나 마케팅 브로셔를 위해 부동산의 메인 룸, 외부 및 평면도를 깔끔한 그리드에 나란히 표시합니다.</p>
  <p><strong>연간 검토 그래픽</strong>: 인기 있는 연말 형식은 각 셀이 한 달의 하이라이트를 나타내는 3×4 그리드입니다. 이 형식은 소셜 플랫폼에서 매우 효과적인 성능을 발휘합니다.</p>

  <br>
  <h2 id="choosing-the-right-grid-layout">올바른 그리드 레이아웃 선택</h2>

  <p>선택한 행과 열의 수는 각 사진이 읽는 방식에 직접적인 영향을 미칩니다. 다음은 몇 가지 일반적인 지침입니다.</p>
  <ul>
    <li><strong>2×2(사진 4장)</strong>: 클래식 정사각형 쿼드. 전/후 쌍 또는 사계절 비교에 적합합니다.</li>
    <li><strong>2×3(사진 6개)</strong>: 세로 방향 격자는 Instagram Stories 또는 A4 인쇄에 적합합니다.</li>
    <li><strong>3×3(사진 9장)</strong>: 제품 쇼케이스에 널리 사용되는 정사각형 그리드입니다.</li>
    <li><strong>1×3(사진 3장, 가로 스트립)</strong>: 타임라인과 유사한 레이아웃으로 단계별 시각적 자료나 진행 상황 사진에 적합합니다.</li>
  </ul>

  <p>사진 방향이 가로 방향과 세로 방향이 혼합되어 있는 경우 개별 셀 확대/축소 및 이동 컨트롤을 사용하여 각 사진을 왜곡 없이 잘립니다.</p>
  
  <br>
  <h2 id="exporting-for-other-platforms">다른 플랫폼으로 내보내기</h2>

  <p>플랫폼마다 권장되는 이미지 크기와 가로 세로 비율이 다릅니다.</p>

  <테이블>
    <머리>
      <tr><th>플랫폼</th><th>권장 크기</th><th>가로세로 비율</th></tr>
    </thead>
    <몸>
      <tr><td>인스타그램 게시물</td><td>1080 × 1080px</td><td>1:1</td></tr>
      <tr><td>인스타그램 가로 모드</td><td>1080 × 566픽셀</td><td>1.91:1</td></tr>
      <tr><td>Twitter/X 게시물</td><td>1200 × 675픽셀</td><td>16:9</td></tr>
      <tr><td>Facebook 게시물</td><td>1200 × 630픽셀</td><td>~1.91:1</td></tr>
      <tr><td>LinkedIn 게시물</td><td>1200 × 628픽셀</td><td>1.91:1</td></tr>
      <tr><td>인쇄(150dpi에서 A4)</td><td>1754 × 1240px</td><td>A4</td></tr>
    </tbody>
  </table>

  <p>THRJ 콜라주 도구에서 내보낼 때 <strong>콜라주 및 미리보기</strong>를 클릭하기 전에 대상 플랫폼과 일치하도록 캔버스 크기를 설정하세요.</p>
  <br>
  <h2 id="frequently-asked-questions">자주 묻는 질문</h2>

  <p><strong>내 휴대전화에 있는 사진을 사용할 수 있나요?</strong> 예. 모바일 브라우저에서는 파일 선택기가 카메라 롤을 직접 엽니다. JPEG, PNG, WebP 및 HEIC 이미지가 모두 지원됩니다(HEIC 변환은 브라우저 지원에 따라 다름).</p>
  <p><strong>사용할 수 있는 최대 사진 수는 몇 장입니까?</strong> 엄격한 제한은 없지만 고해상도 이미지가 포함된 매우 큰 그리드는 상당한 브라우저 메모리를 사용할 수 있습니다. 최상의 성능을 위해서는 소스 이미지를 각각 5MB 미만으로 유지하세요.</p>
  <p><strong>콜라주에 텍스트나 스티커를 추가할 수 있나요?</strong> 콜라주 도구는 격자 구성에 중점을 둡니다. 텍스트를 오버레이하려면 결과 콜라주 이미지에 <a href="/image-meme-generator">밈 생성기</a>를 사용하세요.</p>
  <p><strong>출력은 항상 PNG인가요?</strong> 예. 무손실 품질을 위해 캔버스를 PNG로 내보냅니다. 더 작은 파일 크기를 위해 JPEG가 필요한 경우 나중에 <a href="/image-converter">이미지 변환기</a> 또는 <a href="/image-resizer">이미지 크기 조정기</a>를 통해 출력을 실행하세요.</p>
  <p><strong>Instagram에 업로드한 후 내 콜라주가 흐릿하게 보이는 이유는 무엇입니까?</strong> Instagram은 업로드를 다시 압축합니다. 눈에 띄는 품질 손실을 최소화하려면 콜라주를 1080px 이상으로 내보내고 PNG 또는 고품질 JPEG를 사용하세요.</p>

