  <h1>이미지 워터마크 가이드 — 텍스트 또는 로고 워터마크로 사진을 보호하세요</h1>

  <p>THRJ에서 Image Watermarker 도구를 사용하기 위한 전체 연습입니다. 이 가이드에서는 워터마크 유형 선택부터 완성된 결과 다운로드까지 UI, 주요 컨트롤, 단계별 지침을 스크린샷과 함께 설명합니다. 모든 처리는 업로드가 필요하지 않고 브라우저에서 로컬로 이루어집니다. <a href="/image-watermarker">이미지 워터마커 열기</a></p>

  <br>
  <h2>워터마크란 무엇이며 왜 사용합니까?</h2>

  <p>워터마크는 소스를 식별하거나 무단 사용을 방지하기 위해 이미지 위에 배치되는 눈에 보이거나 반투명한 오버레이(일반적으로 텍스트 또는 로고)입니다. 워터마크는 사진작가, 일러스트레이터, 브랜드에서 온라인으로 공유된 창작물을 보호하기 위해 사용됩니다.</p>

  <p><img src="/screenshots/watermarker/watermarker001.png" alt="워터마커 도구 스크린샷" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>빠른 단계</h2>
  <올>
    <li>메인 메뉴(도구 → 이미지 워터마커)에서 이미지 워터마커를 열거나 <code>/image-watermarker</code>를 방문하세요.</li>
    <li>드래그 앤 앰프; 이미지를 놓기 영역에 놓거나 클릭하여 파일을 찾아 선택하세요.</li>
    <li>라디오 버튼을 사용하여 <strong>텍스트 워터마크</strong> 또는 <strong>로고 워터마크</strong>를 선택합니다.</li>
    <li>워터마크 텍스트를 입력하거나 PNG/SVG 로고 파일을 업로드하세요.</li>
    <li>위치, 크기, 불투명도를 조정하여 원하는 위치에 워터마크를 배치하세요.</li>
    <li><strong>워터마크 적용</strong>을 클릭하여 결과를 미리 본 다음 <strong>다운로드</strong>를 클릭하여 워터마크가 표시된 이미지를 저장하세요.</li>
  </ol>

  <br>
  <h2>스크린샷을 포함한 단계별</h2>

  <h3>1. 이미지 로드</h3>
  <p>드래그 앤 앰프; 드롭 영역을 드롭하거나 클릭하여 장치에서 이미지를 선택합니다. JPEG, PNG, WebP 등 일반적인 웹 형식이 지원됩니다.</p>
  <p><img src="/screenshots/watermarker/watermarker001.png" alt="이미지 로드" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>2. 텍스트나 로고를 선택하고 구성하세요.</h3>
  <p><strong>텍스트 워터마크</strong>를 선택하고 텍스트(예: 이름, 웹사이트 또는 저작권 고지)를 입력하거나 <strong>로고 워터마크</strong>를 선택하고 PNG/SVG 그래픽을 업로드합니다. 가장 깔끔한 결과를 얻으려면 투명한 배경 PNG 또는 SVG 로고를 사용하세요.</p>
  <p><img src="/screenshots/watermarker/watermarker002.png" alt="워터마크 옵션 설정" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>3. 위치, 크기 및 불투명도 조정</h3>
  <p>위치, 비율, 불투명도 컨트롤을 사용하여 워터마크가 나타나는 위치와 강도를 미세 조정하세요. 코너 배치는 눈에 띄지 않습니다. 중앙 배치 또는 타일링으로 더욱 강력하게 보호할 수 있습니다.</p>
  <p><img src="/screenshots/watermarker/watermarker003.png" alt="워터마크 위치 조정" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>4. 미리보기 및 다운로드</h3>
  <p>합성 이미지를 렌더링하고 미리보기에서 검사하려면 <strong>워터마크 적용</strong>을 클릭하세요. 만족스러우면 <strong>다운로드</strong>를 클릭하여 워터마크가 있는 파일을 저장하세요.</p>
  <p><img src="/screenshots/watermarker/watermarker004.png" alt="워터마크가 있는 이미지 다운로드" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>팁 &amp; 자주 묻는 질문</h2>
  <ul>
    <li>모든 처리는 브라우저에서 실행되며 이미지는 어떤 서버에도 업로드되지 않습니다.</li>
    <li>은은한 브랜드 마크에는 낮은 불투명도를 사용합니다. 더 선명한 눈 보호를 위해 불투명도를 높입니다.</li>
    <li>배경이 투명한 로고(PNG 또는 SVG)는 흰색 배경의 로고보다 더 깔끔한 결과를 제공합니다.</li>
    <li>애니메이션 이미지(GIF/WebP)는 내보낼 때 단일 프레임으로 병합됩니다.</li>
  </ul>

  <br>
  <h2>올바른 워터마크 스타일 선택</h2>
  <p><strong>텍스트 워터마크</strong>는 빠르고 유연합니다. <strong>로고 워터마크</strong>는 더욱 전문적이고 브랜드 일관성을 유지합니다. 더 강력한 보호를 위해 중앙 배치나 타일링을 고려해보세요.</p>

  <br>
  <h2>불투명도 지침</h2>
  <테이블>
    <머리>
      <tr><th>워터마크 목적</th><th>권장 불투명도</th></tr>
    </thead>
    <몸>
      <tr><td>미묘한 브랜드 마크(낮은 우선순위)</td><td>15~25%</td></tr>
      <tr><td>표준 저작권 고지</td><td>30~50%</td></tr>
      <tr><td>강력한 가시적 억제력</td><td>60~80%</td></tr>
      <tr><td>대담하고 의도적인 브랜딩</td><td>80~100%</td></tr>
    </tbody>
  </table>

  <br>
  <h2>포지셔닝 전략</h2>
  <p>모서리 배치는 눈에 띄지 않지만 잘라내기가 더 쉽습니다. 중앙 배치는 제거하기가 더 어렵습니다. 타일링으로 인해 제거가 어려워집니다. 더 강력한 보호를 위해 주요 세부정보 위에 위치시키세요.</p><br>
  <h2>최상의 결과를 위한 로고 준비</h2>
  <ul>
    <li>깨끗한 합성을 위해 투명한 배경의 PNG를 사용하세요.</li>
    <li>대형 이미지의 픽셀화를 방지하려면 확장성을 위해 SVG를 사용하세요.</li>
    <li>대부분의 사진 크기에 대해 약 200~400픽셀 너비의 로고를 목표로 하세요.</li>
