  <br>
  <h2>자주 묻는 질문</h2>
  <p><strong>한 번에 여러 이미지에 워터마킹을 할 수 있나요?</strong> 이 도구는 한 번에 하나의 이미지를 처리합니다. 세션 중 마지막 설정을 기억합니다.</p>
