  <h1>Image Resizer: cambia el tamaño de las imágenes de forma rápida y privada en tu navegador</h1>

  <p>Un tutorial completo para usar la herramienta <strong>Image Resizer</strong> en THRJ. Esta guía cubre el flujo de trabajo básico, consejos útiles, referencias de tamaño de plataforma y notas de privacidad para que pueda reducir o escalar imágenes rápidamente sin instalar ningún software. <a href="/image-resizer">Abra el cambio de tamaño de imagen</a></p>

  <p><img src="/screenshots/resizer/Image-resizer001.png" alt="Captura de pantalla de Image Resizer" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>¿Por qué cambiar el tamaño de las imágenes?</h2>

  <p>El cambio de tamaño de la imagen es una de las tareas más frecuentes en los flujos de trabajo de contenido digital. Ya sea un fotógrafo que prepara archivos para un cliente, un blogger que optimiza imágenes para la velocidad de la página o un desarrollador que prueba el diseño de la interfaz de usuario, cambiar el tamaño ayuda a ofrecer las dimensiones y el tamaño de archivo correctos para el trabajo.</p>

  <br>
  <h2>Descripción general</h2>
  <p>Image Resizer facilita cambiar las dimensiones de la imagen, escalarla para web o imprimir y reducir el tamaño del archivo sin salir del navegador. Admite formatos comunes (JPEG, PNG, WebP) y ofrece ajustes preestablecidos para objetivos comunes como publicaciones sociales o miniaturas.</p>

  <br>
  <h2>Pasos rápidos</h2>
  <ol>
    <li>Abra la página Image Resizer: <code>/image-resizer</code>.</li>
    <li>Arrastrar y abrir suelte una imagen o haga clic para seleccionar archivos desde su dispositivo.</li>
    <li>Utilice Alt+Desplazamiento o Pellizcar para acercar y alejar la vista previa de la imagen.</li>
    <li>(Opcional) Ajustar la calidad/compresión de la imagen.</li>
    <li>Haga clic en <strong>Cambiar tamaño</strong> y descargue la imagen redimensionada.</li>
  </ol>

  <br>
  <h2>Paso a paso con capturas de pantalla</h2>

  <h3>1. Sube una imagen</h3>
  <p>Coloca una o más imágenes en el cargador o usa el selector de archivos. El cargador muestra el nombre del archivo, las dimensiones y el tamaño original.</p>
  <p><img src="/screenshots/resizer/Image-resizer002.png" alt="Subir imagen" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>2. Elige tamaño o preestablecido</h3>
  <p>Seleccione un ajuste preestablecido para destinos comunes o escriba un ancho y alto personalizados. Mantenga la relación de aspecto bloqueada para evitar distorsiones a menos que necesite una forma diferente.</p>
  <p><img src="/screenshots/resizer/Image-resizer003.png" alt="Elegir tamaño" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>3. Ajustar la calidad y cambiar el tamaño</h3>
  <p>Elija un nivel de compresión/calidad si desea archivos más pequeños. Haga clic en <strong>Cambiar tamaño</strong>: aparece un indicador de progreso y la imagen redimensionada estará disponible para descargar.</p>
  <p><img src="/screenshots/resizer/Image-resizer004.png" alt="Cambiar el tamaño y descargar" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>Consejos</h2>
  <ul>
    <li>Utilice ajustes preestablecidos para obtener resultados rápidos y consistentes en todas las plataformas sociales.</li>
    <li>Reduzca ligeramente la calidad para ahorrar grandes tamaños de archivos cuando las imágenes son para uso web.</li>
    <li>Mantén la relación de aspecto bloqueada a menos que necesites específicamente una forma diferente.</li>
    <li>Para ediciones por lotes, cargue varios archivos y descargue un ZIP de imágenes redimensionadas.</li>
  </ul>

  <br>
  <h2>Tamaños de imagen estándar por plataforma</h2>
  <tabla>
    <cabeza>
      <tr><th>Destino</th><th>Dimensiones recomendadas</th><th>Notas</th></tr>
    </thead>
    <tcuerpo>
      <tr><td>Publicación de Instagram (cuadrada)</td><td>1080 × 1080 px</td><td>Relación de aspecto 1:1</td></tr>
      <tr><td>Publicación de Instagram (apaisada)</td><td>1080 × 566 px</td><td>Relación de aspecto 1,91:1</td></tr>
      <tr><td>Historias de Instagram/Reels</td><td>1080 × 1920 px</td><td>Relación de aspecto 9:16</td></tr>
      <tr><td>Encabezado Twitter/X</td><td>1500 × 500 px</td><td>Relación de aspecto 3:1</td></tr>
      <tr><td>Imagen de Twitter/X post</td><td>1200 × 675 px</td><td>Relación de aspecto 16:9</td></tr>
      <tr><td>Foto de portada de Facebook</td><td>820 × 312 px</td><td>Se muestra a 820 × 312 en el escritorio</td></tr>
      <tr><td>Banner de empresa de LinkedIn</td><td>1128 × 191 px</td><td></td></tr>
      <tr><td>Miniatura de YouTube</td><td>1280 × 720 px</td><td>Mínimo 640 × 360</td></tr>
      <tr><td>Imagen destacada del blog</td><td>1200 × 630 px</td><td>Estándar OpenGraph</td></tr>
      <tr><td>Producto de comercio electrónico (Amazon)</td><td>2000 × 2000 px</td><td>Mínimo 1000 × 1000</td></tr>
    </tbody>
  </tabla>

  <br>
  <h2>Comprensión de las compensaciones entre la calidad de la imagen y el tamaño del archivo</h2>
  <p>Cuando cambia el tamaño y comprime una imagen, suceden dos cosas: reducción de dimensión (menos píxeles) y compresión (controles deslizantes de calidad). Como regla general, utilice una calidad del 85 % para las imágenes destacadas y del 70 % al 75 % para las miniaturas.</p>

  <br>
  <h2>Privacidad</h2><p>Todo el cambio de tamaño y la compresión se ejecutan completamente en el navegador utilizando la API HTML5 Canvas. Tus imágenes nunca se cargan en un servidor. Esto hace que THRJ Image Resizer sea seguro para imágenes confidenciales, personales o propietarias.</p>

  <br>
  <h2>Preguntas frecuentes</h2>
  <p><strong>¿El cambio de tamaño afecta la calidad de la imagen?</strong> La reducción de las dimensiones descarta los píxeles; conserve siempre una copia original.</p>
  <p><strong>¿Cuál es la diferencia entre cambiar el tamaño y recortar?</strong> El cambio de tamaño escala toda la imagen; recortar selecciona una porción. Utilice recortar y luego cambie el tamaño para obtener mejores resultados.</p>
  <p><strong>¿Puedo cambiar el tamaño a un tamaño de archivo específico?</strong> No directamente; combine dimensiones más bajas con una calidad del 75 al 80 % para reducir el tamaño del archivo.</p>
  <p><strong>¿El cambio de tamaño admite el procesamiento por lotes?</strong> Sí, cargue varios archivos y la herramienta procesará cada uno de ellos y ofrecerá la descarga por lotes.</p>

  <hora/>
  <p>Publicado por THRJ Tech</p>

