  <h1>이미지 크기 조정 도구 - 브라우저에서 비공개로 신속하게 이미지 크기 조정</h1>

  <p>THRJ에서 <strong>이미지 크기 조정기</strong> 도구를 사용하는 방법에 대한 전체 안내입니다. 이 가이드에서는 소프트웨어를 설치하지 않고도 이미지를 빠르게 축소하거나 크기를 조정할 수 있도록 기본 작업 과정, 유용한 팁, 플랫폼 크기 참조 및 개인 정보 보호 참고 사항을 다룹니다. <a href="/image-resizer">이미지 크기 조정 도구 열기</a></p>

  <p><img src="/screenshots/resizer/Image-resizer001.png" alt="이미지 크기 조정 스크린샷" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>왜 이미지 크기를 조정하나요?</h2>

  <p>이미지 크기 조정은 디지털 콘텐츠 워크플로에서 가장 자주 수행되는 작업 중 하나입니다. 클라이언트를 위해 파일을 준비하는 사진작가, 페이지 속도에 맞게 이미지를 최적화하는 블로거, UI 레이아웃을 테스트하는 개발자 등 크기 조정은 작업에 적합한 크기와 파일 크기를 제공하는 데 도움이 됩니다.</p>

  <br>
  <h2>개요</h2>
  <p>Image Resizer를 사용하면 브라우저를 종료하지 않고도 이미지 크기를 쉽게 변경하고, 웹이나 인쇄에 맞게 크기를 조정하고, 파일 크기를 줄일 수 있습니다. 일반적인 형식(JPEG, PNG, WebP)을 지원하고 소셜 게시물이나 썸네일과 같은 일반적인 대상에 대한 사전 설정을 제공합니다.</p>

  <br>
  <h2>빠른 단계</h2>
  <올>
    <li>이미지 크기 조정기 페이지를 엽니다: <code>/image-resizer</code>.</li>
    <li>드래그 앤 앰프; 이미지를 드롭하거나 클릭하여 기기에서 파일을 선택하세요.</li>
    <li>Alt+스크롤 또는 핀치 기능을 사용하여 이미지 미리보기를 확대하거나 축소하세요.</li>
    <li>(선택사항) 이미지 품질/압축을 조정합니다.</li>
    <li><strong>크기 조정</strong>을 클릭하고 크기가 조정된 이미지를 다운로드하세요.</li>
  </ol>

  <br>
  <h2>스크린샷을 포함한 단계별</h2>

  <h3>1. 이미지 업로드</h3>
  <p>하나 이상의 이미지를 업로더에 드롭하거나 파일 선택기를 사용하세요. 업로더는 파일 이름, 크기, 원본 크기를 표시합니다.</p>
  <p><img src="/screenshots/resizer/Image-resizer002.png" alt="이미지 업로드" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>2. 크기 또는 사전 설정 선택</h3>
  <p>일반 대상에 대한 사전 설정을 선택하거나 맞춤 너비 및 높이를 입력하세요. 다른 모양이 필요한 경우를 제외하고 왜곡을 방지하려면 가로세로 비율을 잠근 상태로 유지하세요.</p>
  <p><img src="/screenshots/resizer/Image-resizer003.png" alt="크기 선택" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>3. 품질 조정 및 크기 조정</h3>
  <p>더 작은 파일을 원할 경우 압축/품질 수준을 선택하세요. <strong>크기 조정</strong>을 클릭하면 진행률 표시기가 나타나고 크기가 조정된 이미지를 다운로드할 수 있게 됩니다.</p>
  <p><img src="/screenshots/resizer/Image-resizer004.png" alt="크기 조정 및 다운로드" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>팁</h2>
  <ul>
    <li>소셜 플랫폼 전반에서 빠르고 일관된 결과를 얻으려면 사전 설정을 사용하세요.</li>
    <li>웹용 이미지인 경우 파일 크기를 크게 절약하기 위해 품질을 약간 낮춥니다.</li>
    <li>특별히 다른 모양이 필요한 경우가 아니라면 가로세로 비율을 고정된 상태로 유지하세요.</li>
    <li>일괄 수정의 경우 여러 파일을 업로드하고 크기가 조정된 이미지의 ZIP을 다운로드하세요.</li>
  </ul>

  <br>
  <h2>플랫폼별 표준 이미지 크기</h2>
  <테이블>
    <머리>
      <tr><th>대상</th><th>권장 크기</th><th>참고</th></tr>
    </thead>
    <몸>
      <tr><td>Instagram 게시물(정사각형)</td><td>1080 × 1080px</td><td>가로세로 비율 1:1</td></tr>
      <tr><td>Instagram 게시물(가로)</td><td>1080 × 566px</td><td>가로세로 비율 1.91:1</td></tr>
      <tr><td>Instagram 스토리/릴</td><td>1080 × 1920픽셀</td><td>9:16 화면 비율</td></tr>
      <tr><td>Twitter / X 헤더</td><td>1500 × 500픽셀</td><td>3:1 화면비</td></tr>
      <tr><td>Twitter / X 게시물 이미지</td><td>1200 × 675px</td><td>가로세로 비율 16:9</td></tr>
      <tr><td>Facebook 표지 사진</td><td>820 × 312픽셀</td><td>데스크톱에서 820×312로 표시</td></tr>
      <tr><td>LinkedIn 회사 배너</td><td>1128 × 191픽셀</td><td></td></tr>
      <tr><td>YouTube 썸네일</td><td>1280 × 720픽셀</td><td>최소 640 × 360</td></tr>
      <tr><td>블로그 히어로 이미지</td><td>1200 × 630픽셀</td><td>OpenGraph 표준</td></tr>
      <tr><td>전자상거래 제품(Amazon)</td><td>2000 × 2000픽셀</td><td>최소 1000 × 1000</td></tr>
    </tbody>
  </table>

  <br>
  <h2>이미지 품질과 파일 크기 균형 이해</h2>
  <p>이미지 크기를 조정하고 압축하면 크기 감소(픽셀 수 감소)와 압축(품질 슬라이더 컨트롤)이라는 두 가지 일이 발생합니다. 일반적으로 히어로 이미지에는 품질을 85%, 썸네일에는 70~75%를 사용합니다.</p>

  <br>
  <h2>개인정보 보호</h2><p>모든 크기 조정 및 압축은 HTML5 Canvas API를 사용하여 완전히 브라우저 내에서 실행됩니다. 귀하의 이미지는 서버에 업로드되지 않습니다. 따라서 THRJ Image Resizer는 기밀, 개인 또는 독점 이미지에 대해 안전합니다.</p>

  <br>
  <h2>자주 묻는 질문</h2>
  <p><strong>크기 조정이 이미지 품질에 영향을 미치나요?</strong> 크기를 줄이면 픽셀이 삭제됩니다. 항상 원본을 보관하세요.</p>
  <p><strong>크기 조정과 자르기의 차이점은 무엇입니까?</strong> 크기 조정은 전체 이미지의 크기를 조정합니다. 자르기는 일부를 선택합니다. 최상의 결과를 얻으려면 자르기를 사용한 다음 크기를 조정하세요.</p>
  <p><strong>특정 파일 크기로 크기를 조정할 수 있나요?</strong> 직접적으로는 불가능합니다. 파일 크기를 줄이려면 낮은 크기와 품질을 75~80% 결합하세요.</p>
  <p><strong>리사이저는 일괄 처리를 지원합니까?</strong> 예 — 여러 파일을 업로드하면 도구가 각각을 처리하고 일괄 다운로드를 제공합니다.</p>

