      <tr><td>WebP</td><td>Oui</td><td>Oui</td><td>Oui</td><td>Images Web (navigateurs modernes)</td></tr>
      <tr><td>AVIF</td><td>Oui</td><td>Oui</td><td>Oui</td><td>Images Web (meilleure compression)</td></tr>
      <tr><td>GIF</td><td>1 bit</td><td>Oui</td><td>Oui (256 couleurs)</td><td>Animations simples, icônes</td></tr>
      <tr><td>BMP</td><td>Non</td><td>Non</td><td>Oui</td><td>Applications Windows héritées</td></tr>
      <tr><td>ICO</td><td>Oui</td><td>Non</td><td>Oui</td><td>Favicons, icônes de bureau</td></tr>
