  <h2>Confidentialité</h2>
  <p>Toutes les conversions s''effectuent localement dans votre navigateur ; aucun fichier n''est téléchargé sur un serveur. Cela signifie que vous pouvez convertir en toute sécurité des images sensibles ou confidentielles sans vous soucier des données qui quittent votre appareil.</p>

  <br>
  <h2>Questions fréquemment posées</h2>
  <p><strong>Pourquoi mon JPEG converti est-il beaucoup plus grand que le JPEG d''origine ?</strong> Le processus de conversion décode le JPEG d''origine dans un tampon de pixels bruts, puis le réencode. Si l''original a été fortement compressé, la version réencodée avec un paramètre de qualité supérieure sera plus grande. Ajustez le curseur de qualité vers le bas pour réduire la taille du fichier.</p>

  <p><strong>Puis-je convertir plusieurs images à la fois ?</strong> Actuellement, l''outil traite une image à la fois. Pour les conversions par lots, vous pouvez réutiliser l''outil rapidement en faisant glisser l''image suivante après chaque conversion.</p>

  <p><strong>Pourquoi AVIF ne fonctionne-t-il pas dans mon navigateur ?</strong> L''encodage AVIF nécessite la prise en charge par le navigateur de l''API <code>canvas.toBlob()</code> avec AVIF. La plupart des navigateurs modernes le prennent en charge, mais pas les anciennes versions. Basculez vers WebP comme solution de secours si AVIF n''est pas disponible.</p>

  <p><strong>Puis-je convertir une page PDF en image ?</strong> Le convertisseur d''image gère les fichiers image. Pour convertir des pages PDF en images, utilisez le <a href="/pdf-converter">PDF Converter</a> sur THRJ.</p>

