      <tr><td>GIF</td><td>1 bit</td><td>Sí</td><td>Sí (256 colores)</td><td>Animaciones simples, iconos</td></tr>
      <tr><td>BMP</td><td>No</td><td>No</td><td>Sí</td><td>Aplicaciones heredadas de Windows</td></tr>
      <tr><td>ICO</td><td>Sí</td><td>No</td><td>Sí</td><td>Favicons, iconos de escritorio</td></tr>
    </tbody>
  </tabla>

  <br>
  <h2>Privacidad</h2>
  <p>Toda la conversión ocurre localmente en su navegador; no se cargan archivos en ningún servidor. Esto significa que puede convertir de forma segura imágenes sensibles o confidenciales sin preocuparse de que los datos salgan de su dispositivo.</p>

  <br>
  <h2>Preguntas frecuentes</h2>
  <p><strong>¿Por qué mi JPEG convertido es mucho más grande que el JPEG original?</strong> El proceso de conversión decodifica el JPEG original en un búfer de píxeles sin formato y luego lo vuelve a codificar. Si el original estaba muy comprimido, la versión recodificada con una configuración de mayor calidad será más grande. Ajuste el control deslizante de calidad hacia abajo para reducir el tamaño del archivo.</p>

  <p><strong>¿Puedo convertir varias imágenes a la vez?</strong> Actualmente, la herramienta procesa una imagen a la vez. Para conversiones por lotes, puede reutilizar la herramienta rápidamente arrastrando la siguiente imagen después de cada conversión.</p>

  <p><strong>¿Por qué AVIF no funciona en mi navegador?</strong> La codificación AVIF requiere compatibilidad del navegador con la API <code>canvas.toBlob()</code> con AVIF. La mayoría de los navegadores modernos admiten esto, pero es posible que las versiones anteriores no. Cambie a WebP como alternativa si AVIF no está disponible.</p>

  <p><strong>¿Puedo convertir una página PDF en una imagen?</strong> El conversor de imágenes maneja archivos de imagen. Para convertir páginas PDF en imágenes, utilice el <a href="/pdf-converter">PDF Converter</a> en THRJ.</p>

