</div>', content_ko='<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe WPC'', ''Segoe UI'', system-ui, ''Ubuntu'', ''Droid Sans'', sans-serif; 글꼴 크기: 14px; 줄 높이: 1.6; 색상: #000000;">

  <h1>이미지 변환기 — 브라우저에서 이미지 형식 간 변환(JPG, PNG, WebP, AVIF, BMP, GIF, ICO)</h1>

  <p>THRJ의 <strong>이미지 변환기</strong>에 대한 전체 가이드입니다. 이 문서에서는 파일을 서버에 업로드하지 않고도 형식 간에 이미지를 변환하고, 투명성을 유지하고, ICO 파비콘 파일을 만들고, 모든 사용 사례에 적합한 형식을 선택하는 방법을 설명합니다. <a href="/image-converter">이미지 변환기 열기</a></p>

  <br>
  <h2>이미지 형식이 중요한 이유</h2>

  <p>모든 이미지 형식은 서로 다른 목적으로 설계되었으며 잘못된 형식을 선택하면 파일 크기가 커지거나 투명성이 떨어지거나 품질이 저하될 수 있습니다. 장단점을 이해하면 언제나 올바른 형식을 선택하는 데 도움이 됩니다.</p>

  <ul>
    <li><strong>JPEG(JPG)</strong>: 사진 및 복잡한 색상 그라데이션에 가장 적합합니다. 손실이 있는 압축은 작은 파일을 생성하지만 반복적으로 저장하면 품질이 저하됩니다. 투명성을 지원하지 않습니다.</li>
    <li><strong>PNG</strong>: 완전한 투명도를 지원하는 무손실 압축입니다. JPEG보다 파일 크기가 크지만 스크린샷, 로고, 아이콘 및 선명한 가장자리와 투명도가 중요한 모든 이미지에 이상적입니다.</li>
    <li><strong>WebP</strong>: 동일한 품질에서 파일 크기에 있어서 JPEG와 PNG를 모두 능가하는 Google의 최신 형식입니다. 투명성과 애니메이션을 지원합니다. 웹페이지에 적합합니다.</li>
    <li><strong>AVIF</strong>: 압축률이 뛰어난 차세대 형식입니다. 가장 작은 파일을 고품질로 생성하고 투명성을 지원합니다. 브라우저 지원은 이제 2024년부터 주류가 되었습니다.</li>
    <li><strong>BMP</strong>: 비압축 비트맵 형식으로 일반적으로 다른 옵션보다 훨씬 큽니다. 일부 레거시 Windows 애플리케이션에서 사용됩니다.</li>
    <li><strong>GIF</strong>: 애니메이션을 지원하는 8비트 색상. 애니메이션의 경우 WebP 및 APNG로 대체되지만 여전히 모든 곳에서 널리 지원됩니다.</li>
    <li><strong>ICO</strong>: Windows 아이콘 형식으로 브라우저 파비콘과 바탕 화면 아이콘에 사용됩니다. 단일 파일 컨테이너에 하나 이상의 이미지 크기가 포함되어 있습니다.</li>
  </ul>

  <br>
  <h2>개요</h2>

  <p>이미지 변환기는 브라우저에서 완전히 실행되므로 업로드가 필요하지 않습니다. 이미지를 디코딩하고, 오프스크린 캔버스에 그린 다음, 선택한 대상 형식으로 내보냅니다. 지원되는 출력에는 JPG, PNG, WebP, AVIF, BMP, GIF 및 ICO가 포함됩니다. TIFF는 입력 형식으로 지원됩니다(브라우저에서 디코딩됨).</p>

  <br>
  <h2>빠른 단계</h2>

  <올>
    <li>이미지 변환기 페이지를 엽니다: <code>/image-converter</code>.</li>
    <li>드래그 앤 앰프; 이미지를 드롭하거나 클릭하여 파일을 선택하세요.</li>
    <li>버튼에서 출력 형식을 선택하세요.</li>
    <li>(ICO의 경우) 원하는 아이콘 크기를 선택하고 <strong>변환</strong>을 클릭하세요.</li>
    <li><strong>다운로드</strong>를 사용하여 변환된 이미지를 다운로드하세요.</li>
  </ol>

  <br>
  <h2>스크린샷을 포함한 단계별</h2>

  <h3>1. 이미지 업로드</h3>
  <p>파일을 업로드 영역에 놓거나 파일 선택기를 사용하세요. 이 도구는 적절한 기본값을 자동 선택합니다.</p>
  <p><img src="/screenshots/image-converter/image-converter-002.png" alt="업로드" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <h3>2. 형식을 선택하고 변환하세요</h3>
  <p>대상 형식을 선택하고 <strong>변환</strong>을 클릭하세요. 미리보기에는 변환된 결과가 표시되며 이동 및 확대/축소가 지원됩니다.</p>
  <p><img src="/screenshots/image-converter/image-converter-003.png" alt="변환" style="max-width:100%;height:auto;display:block;margin:0.75rem 0;" /></p>

  <br>
  <h2>팁</h2>
  <ul>
    <li>투명도를 유지하려면 PNG, WebP 또는 AVIF를 사용하세요.</li>
    <li>사진의 경우 일반적으로 JPG 또는 AVIF가 크기/품질 측면에서 가장 좋습니다.</li>
    <li>ICO 내보내기는 단일 크기의 아이콘을 생성합니다. 파비콘에 필요한 크기를 선택하세요.</li>
  </ul>

  <br>
  <h2>전환 시기 - 실제 시나리오</h2>

  <p><strong>스크린샷 PNG를 JPEG로 변환</strong>: 스크린샷을 공유해야 하지만 PNG가 이메일에 보내기에는 너무 큰 경우 일반적으로 85% 품질의 JPEG로 변환하면 시각적 차이가 거의 눈에 띄지 않고 파일이 60~75% 정도 줄어듭니다.</p>

  <p><strong>JPEG 사진을 웹사이트용 WebP로 변환</strong>: WebP 파일은 일반적으로 동일한 품질에서 JPEG보다 25~35% 더 작습니다. WebP로 전환하면 SEO에 중요한 페이지 로드 속도와 핵심 웹 바이탈 점수가 의미 있게 향상될 수 있습니다.</p>

  <p><strong>파비콘 ICO 만들기</strong>: 브라우저 파비콘에는 전통적으로 특정 크기(16×16, 32×32, 48×48)의 ICO 형식이 필요합니다. 변환기를 사용하면 크기를 선택하고 직접 내보낼 수 있습니다. 최신 브라우저의 경우 32×32 PNG도 작동하지만 ICO는 이전 브라우저와 더 나은 호환성을 제공합니다.</p><p><strong>흰색 배경 제거</strong>: 투명도가 필요하지만 JPEG(투명도를 저장할 수 없음)가 있는 경우 먼저 배경을 제거한 다음 PNG 또는 WebP로 내보내는 편집 도구가 필요합니다.</p>

  <br>
  <h2>형식 비교표</h2>
  <테이블>
    <머리>
      <tr><th>형식</th><th>투명도</th><th>애니메이션</th><th>무손실 옵션</th><th>일반적인 사용</th></tr>
    </thead>
    <몸>
      <tr><td>JPEG</td><td>아니요</td><td>아니요</td><td>아니요</td><td>사진, 복잡한 이미지</td></tr>
      <tr><td>PNG</td><td>예</td><td>아니요</td><td>예</td><td>스크린샷, 로고, 아이콘</td></tr>
      <tr><td>WebP</td><td>예</td><td>예</td><td>예</td><td>웹 이미지(최신 브라우저)</td></tr>
      <tr><td>AVIF</td><td>예</td><td>예</td><td>예</td><td>웹 이미지(최고 압축)</td></tr>
      <tr><td>GIF</td><td>1비트</td><td>예</td><td>예(256색)</td><td>간단한 애니메이션, 아이콘</td></tr>
      <tr><td>BMP</td><td>아니요</td><td>아니요</td><td>예</td><td>레거시 Windows 앱</td></tr>
      <tr><td>ICO</td><td>예</td><td>아니요</td><td>예</td><td>파비콘, 바탕화면 아이콘</td></tr>
    </tbody>
  </table>

  <br>
  <h2>개인정보 보호</h2>
  <p>모든 변환은 브라우저에서 로컬로 발생합니다. 어떤 서버에도 파일이 업로드되지 않습니다. 이는 데이터가 기기 외부로 유출될 염려 없이 민감하거나 기밀인 이미지를 안전하게 변환할 수 있음을 의미합니다.</p>

  <br>
  <h2>자주 묻는 질문</h2>
  <p><strong>변환된 JPEG가 원본 JPEG보다 훨씬 큰 이유는 무엇입니까?</strong> 변환 프로세스에서는 원본 JPEG를 원시 픽셀 버퍼로 디코딩한 다음 다시 인코딩합니다. 원본이 고도로 압축된 경우 더 높은 품질 설정으로 다시 인코딩된 버전은 더 커집니다. 파일 크기를 줄이려면 품질 슬라이더를 아래로 조정하세요.</p>

  <p><strong>한 번에 여러 이미지를 변환할 수 있나요?</strong> 현재 도구는 한 번에 하나의 이미지를 처리합니다. 일괄 변환의 경우 각 변환 후 다음 이미지를 드래그하여 도구를 빠르게 재사용할 수 있습니다.</p>

  <p><strong>내 브라우저에서 AVIF가 작동하지 않는 이유는 무엇입니까?</strong> AVIF 인코딩에는 AVIF가 포함된 <code>canvas.toBlob()</code> API에 대한 브라우저 지원이 필요합니다. 대부분의 최신 브라우저는 이를 지원하지만 이전 버전은 지원하지 않을 수 있습니다. AVIF를 사용할 수 없는 경우 대체 수단으로 WebP로 전환하세요.</p>

  <p><strong>PDF 페이지를 이미지로 변환할 수 있나요?</strong> 이미지 변환기는 이미지 파일을 처리합니다. PDF 페이지를 이미지로 변환하려면 THRJ의 <a href="/pdf-converter">PDF 변환기</a>를 사용하세요.</p>

